-- ----------------------------
-- Table structure for attribute
-- ----------------------------
DROP TABLE IF EXISTS `attribute`;
CREATE TABLE `attribute`  (
  `attr_id` smallint(5) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `attr_name` varchar(32) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '属性名称',
  `cat_id` smallint(5) UNSIGNED NOT NULL COMMENT '外键，类型id',
  `attr_sel` enum('only','many') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT 'only' COMMENT 'only:输入框(唯一)  many:后台下拉列表/前台单选框',
  `attr_write` enum('manual','list') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT 'manual' COMMENT 'manual:手工录入  list:从列表选择',
  `attr_vals` text CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '可选值列表信息,例如颜色：白色,红色,绿色,多个可选值通过空格分隔',
  `delete_time` int(11) NULL DEFAULT NULL COMMENT '删除时间标志',
  PRIMARY KEY (`attr_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 15 CHARACTER SET = utf8 COLLATE = utf8_unicode_ci ROW_FORMAT = DYNAMIC;

