DROP TABLE IF EXISTS `category`;
CREATE TABLE `category`  (
  `cat_id` int(32) NOT NULL AUTO_INCREMENT COMMENT '分类唯一ID',
  `cat_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '分类名称',
  `cat_pid` int(32) NULL DEFAULT NULL COMMENT '分类父ID',
  `cat_level` int(4) NULL DEFAULT NULL COMMENT '分类层级 0: 顶级 1:二级 2:三级',
  `cat_deleted` int(2) NULL DEFAULT NULL COMMENT '是否删除 1为删除',
  `cat_icon` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL COMMENT '分类图片',
  `cat_src` text CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL,
  PRIMARY KEY (`cat_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 24 CHARACTER SET = utf8 COLLATE = utf8_unicode_ci ROW_FORMAT = DYNAMIC;

