-- ----------------------------
-- Table structure for goods
-- ----------------------------
DROP TABLE IF EXISTS `goods`;
CREATE TABLE `goods`  (
  `goods_id` mediumint(8) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '商品名称',
  `goods_price` decimal(10, 2) NOT NULL COMMENT '商品价格',
  `goods_number` int(8) UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品数量',
  `goods_weight` smallint(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品重量',
  `cat_id` smallint(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型id',
  `goods_introduce` longtext CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL COMMENT '商品详情介绍',
  `goods_big_logo` char(128) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT '图片logo大图',
  `goods_small_logo` char(128) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT '图片logo小图',
  `is_del` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '0' COMMENT '0:正常  1:删除',
  `add_time` int(11) NOT NULL COMMENT '添加商品时间',
  `upd_time` int(11) NOT NULL COMMENT '修改商品时间',
  `delete_time` int(11) NULL DEFAULT NULL COMMENT '软删除标志字段',
  `cat_one_id` smallint(5) NULL DEFAULT 0 COMMENT '一级分类id',
  `cat_two_id` smallint(5) NULL DEFAULT 0 COMMENT '二级分类id',
  `cat_three_id` smallint(5) NULL DEFAULT 0 COMMENT '三级分类id',
  `hot_mumber` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '热卖数量',
  `is_promote` smallint(5) NULL DEFAULT 0 COMMENT '是否促销',
  `goods_state` int(11) NULL DEFAULT 0 COMMENT '商品状态 0: 未通过 1: 审核中 2: 已',
  PRIMARY KEY (`goods_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 50 CHARACTER SET = utf8 COLLATE = utf8_unicode_ci ROW_FORMAT = DYNAMIC;

