-- ----------------------------
-- Table structure for goods_attr
-- ----------------------------
DROP TABLE IF EXISTS `goods_attr`;
CREATE TABLE `goods_attr`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `goods_id` mediumint(8) UNSIGNED NOT NULL COMMENT '商品id',
  `attr_id` smallint(5) UNSIGNED NOT NULL COMMENT '属性id',
  `attr_value` text CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '商品对应属性的值',
  `add_price` decimal(8, 2) NULL DEFAULT NULL COMMENT '该属性需要额外增加的价钱',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 248 CHARACTER SET = utf8 COLLATE = utf8_unicode_ci ROW_FORMAT = DYNAMIC;

