DROP TABLE IF EXISTS `manager`;
CREATE TABLE `manager`  (
  `mg_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `mg_name` varchar(32) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '名称',
  `mg_pwd` char(64) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '密码',
  `mg_time` int(10) UNSIGNED NOT NULL COMMENT '注册时间',
  `role_id` tinyint(11) NOT NULL COMMENT '角色id',
  `mg_mobile` varchar(32) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL,
